sqlGroup.select:
select a.id, a.name AS name, a.device_repair_id as deviceRepairId, dr.name as deviceRepairName, a.job_type as jobType, a.prod_line_or_dept as prodLineOrDept, a.approval_status as approvalStatus, a.status as status, date_format( a.created_time, '%Y-%m-%d %H:%i:%s' ) as createdTime, cs.`name` AS createdStaffName
from jml_parts_purchase a left join jml_staff cs ON a.created_staff_id = cs.id left join jml_device_repair as dr on a.device_repair_id = dr.id
and a.created_staff_id = #{staff.staffId}
and (a.prod_line_or_dept = #{staff.prodLineOrDept} and a.status !='DTJ') or a.created_staff_id = #{staff.staffId}
and a.status !='DTJ'
and (a.name like '%${multiFiled}%')
and a.created_time >= str_to_date(#{startDate},'%Y-%m-%d')
and a.created_time <= date_add(str_to_date(#{endDate},'%Y-%m-%d'),interval 1 day)
and a.prod_line_or_dept = #{prodLineOrDept}
and a.created_staff_id = #{createdStaffId}
and a.approval_status = #{approvalStatus}
group by a.id order by a.update_time desc
